parameters.jsCode:
// ============================================================
// Validar Payload
// ------------------------------------------------------------
// El backend BookMatch nos envía:
//   { playlistId, userId, prompt, size, genres, mood, language,
//     catalogSample: [{ id, title, author }], callbackUrl, callbackSecret }
// Validamos y normalizamos antes de ir al LLM.
// ============================================================

const payload = $json.body;
if (!payload) {
  throw new Error('Request body is missing');
}

const {
  playlistId,
  userId,
  prompt,
  size,
  genres,
  mood,
  language,
  catalogSample,
  callbackUrl,
  callbackSecret
} = payload;

if (!Number.isInteger(playlistId) || playlistId <= 0) {
  throw new Error(`playlistId inválido: ${playlistId}`);
}
if (!Number.isInteger(userId) || userId <= 0) {
  throw new Error(`userId inválido: ${userId}`);
}
if (!prompt || typeof prompt !== 'string' || prompt.length < 5) {
  throw new Error('prompt vacío o demasiado corto');
}
if (!callbackUrl || typeof callbackUrl !== 'string' || !/^https?:\/\//.test(callbackUrl)) {
  throw new Error(`callbackUrl inválido: ${callbackUrl}`);
}
if (!Array.isArray(catalogSample) || catalogSample.length === 0) {
  throw new Error('catalogSample vacío: el backend debe enviar al menos un libro');
}

const safeSample = catalogSample
  .filter((b) => Number.isInteger(b?.id) && typeof b?.title === 'string')
  .slice(0, 80);

const allowedIds = safeSample.map((b) => b.id);

return {
  playlistId,
  userId,
  prompt: prompt.trim(),
  size: Number.isInteger(size) ? Math.max(3, Math.min(25, size)) : 8,
  genres: Array.isArray(genres) ? genres.slice(0, 10) : [],
  mood: typeof mood === 'string' ? mood.slice(0, 80) : null,
  language: typeof language === 'string' ? language.slice(0, 20) : 'es',
  catalogSample: safeSample,
  allowedIds,
  callbackUrl,
  callbackSecret: callbackSecret || null,
  startTime: Date.now()
};

// ============================================================
// Construir Prompt LLM
// ------------------------------------------------------------
// Prepara `systemPrompt` y `userPrompt` en formato JSON-strict
// para que el modelo solo use IDs del `catalogSample` real.
// ============================================================

const data = $json;

const sampleList = data.catalogSample
  .map((b) => `- [${b.id}] ${b.title}${b.author ? ' — ' + b.author : ''}`)
  .join('\n');

const systemPrompt = `Eres BookMatch, un asistente experto en libros.
Tu tarea es generar una playlist de lectura basada en la petición del usuario
seleccionando EXCLUSIVAMENTE libros del catálogo proporcionado.

Reglas estrictas:
1. Usa únicamente IDs presentes en CATALOGO. Si inventas un ID, la playlist se rechaza.
2. No repitas el mismo id.
3. Devuelve entre 3 y ${data.size} libros.
4. El idioma de title/description es "${data.language}".
5. Responde ÚNICAMENTE con JSON válido que cumpla este esquema:
{
  "title": string (<= 80 chars),
  "description": string (<= 400 chars),
  "items": [ { "catalogBookId": number, "note": string | null } ]
}
Nada de texto fuera del JSON.`;

const userPrompt = `PETICIÓN DEL USUARIO:
"""
${data.prompt}
"""

Géneros preferidos: ${data.genres.length ? data.genres.join(', ') : 'no especificados'}
Estado de ánimo: ${data.mood || 'no especificado'}
Tamaño deseado: ${data.size} libros

CATALOGO (id — título — autor):
${sampleList}`;

return {
  ...data,
  systemPrompt,
  userPrompt
};

parameters.jsonBody:
={{ {
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: $json.systemPrompt },
    { role: 'user',   content: $json.userPrompt }
  ],
  response_format: { type: 'json_object' },
  temperature: 0.4,
  max_tokens: 1024
} }}

parameters.jsCode:
// ============================================================
// Parsear Respuesta LLM
// ------------------------------------------------------------
// Extrae el JSON del `choices[0].message.content`, valida campos
// e intersecta `catalogBookId` contra `allowedIds` para descartar
// libros inventados por el modelo. Además genera una URL de portada
// vía Pollinations.ai (SCRUM-181): Groq NO genera imágenes, así que
// usamos este servicio gratuito (modelo flux) con seed=playlistId
// para que la URL sea estable.
// ============================================================

const prev = $('Construir Prompt').item.json;
const response = $json;

let parsed = null;
try {
  const content = response?.choices?.[0]?.message?.content || '';
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (err) {
  throw new Error('Respuesta LLM no es JSON válido: ' + (err?.message || err));
}

if (!parsed || typeof parsed !== 'object') {
  throw new Error('Respuesta LLM vacía o no es un objeto');
}

const allowed = new Set(prev.allowedIds);

const rawItems = Array.isArray(parsed.items) ? parsed.items : [];
const cleanItems = [];
const seen = new Set();
for (const it of rawItems) {
  const id = Number(it?.catalogBookId);
  if (!Number.isInteger(id) || !allowed.has(id) || seen.has(id)) continue;
  seen.add(id);
  cleanItems.push({
    catalogBookId: id,
    position: cleanItems.length + 1,
    note: typeof it?.note === 'string' ? it.note.slice(0, 500) : null
  });
  if (cleanItems.length >= prev.size) break;
}

if (cleanItems.length === 0) {
  return {
    ...prev,
    aiStatus: 'error',
    aiErrorMessage: 'El modelo no devolvió IDs válidos del catálogo.',
    aiTitle: null,
    aiDescription: null,
    aiCoverUrl: null,
    aiItems: []
  };
}

const aiTitle = typeof parsed.title === 'string' ? parsed.title.slice(0, 100) : null;
const aiDescription = typeof parsed.description === 'string' ? parsed.description.slice(0, 2000) : null;

// --- Portada vía Pollinations (gratis, sin API key) ---
const coverPromptParts = [
  'book collection cover art',
  aiTitle || prev.prompt.slice(0, 80),
  prev.genres && prev.genres.length ? prev.genres.slice(0, 3).join(' ') : '',
  prev.mood || '',
  'stylized vibrant painterly minimalist no text no letters'
].filter(Boolean);
const coverPrompt = coverPromptParts.join(', ').slice(0, 300);
const encoded = encodeURIComponent(coverPrompt);
const aiCoverUrl = `https://image.pollinations.ai/prompt/${encoded}?width=800&height=800&nologo=true&model=flux&seed=${prev.playlistId}`;

return {
  ...prev,
  aiStatus: 'success',
  aiErrorMessage: null,
  aiTitle,
  aiDescription,
  aiCoverUrl,
  aiItems: cleanItems,
  processingTime: Date.now() - (prev.startTime || Date.now())
};

parameters.jsonBody:
={{ {
  status: $json.aiStatus,
  errorMessage: $json.aiErrorMessage,
  title: $json.aiTitle,
  description: $json.aiDescription,
  coverUrl: $json.aiCoverUrl,
  items: $json.aiItems
} }}

