// ============================================================
// Preparar Error
// ------------------------------------------------------------
// Rama de fallo: si Groq o el parser dejan el pipeline sin salida
// usable, notificamos al backend con status='error' para que
// marque la playlist como fallida (`[AI_FAILED] ...`).
// ============================================================

const prev = $('Validar Payload').item.json;
const err = $json.error || $json;

return {
  ...prev,
  aiStatus: 'error',
  aiErrorMessage: (err?.message || 'Fallo en generación IA').slice(0, 500),
  aiTitle: null,
  aiDescription: null,
  aiItems: []
};

parameters.jsonBody:
={{ {
  status: 'error',
  errorMessage: $json.aiErrorMessage,
  title: null,
  description: null,
  items: []
} }}
